/**
 * 在线词典：本机没装牛津词典（或本地词典服务不在）时，点词也查得到东西。
 *
 * 走 dictionaryapi.dev（不要 key、带 CORS，浏览器里直接问），拿回音标、词性、
 * 英文释义和例句，整理成卡片认识的 LanguageInsight —— 结果就在卡片里铺开，
 * 不开新页、不跳走。查不到（或者网络不通）就返回 null，让调用方接自己的兜底。
 *
 * 这台线上词典只有英文释义：卡片见到 meaningsZh 是空的，会把英文释义顶到
 * 第一行，并标一句「在线词典」，让人知道这条不是牛津的。
 */
import { lemmaCandidates } from "@leafia/shared";
import type { LanguageInsight } from "@leafia/shared";

const ENDPOINT = "https://api.dictionaryapi.dev/api/v2/entries/en";
/** 等这么久还不回来就别等了：卡片上不能一直转圈。 */
const TIMEOUT_MS = 6500;

interface OnlineDefinition {
  definition?: string;
  example?: string;
}

interface OnlineMeaning {
  partOfSpeech?: string;
  definitions?: OnlineDefinition[];
}

interface OnlineEntry {
  word?: string;
  phonetic?: string;
  phonetics?: { text?: string }[];
  meanings?: OnlineMeaning[];
}

/** 一次最多铺几条释义、几条例句：卡片是随手看一眼的地方。 */
const MAX_SENSES = 3;
const MAX_EXAMPLES = 2;

export async function lookupOnlineDictionary(
  word: string,
): Promise<LanguageInsight | null> {
  const term = word.trim();
  if (!term) return null;

  // 它只认原形词条：先查点的那个词，再挨个试原形（reported → report）。
  // 最多试三个：卡片上不能让人一直看着转圈。
  const attempts = [term.toLowerCase(), ...lemmaCandidates(term)].slice(0, 3);
  for (const candidate of attempts) {
    const found = await fetchEntry(candidate);
    if (found) {
      // 大字仍旧是点中的那个词；查的是谁，落在 lemma 里。
      return { ...found, term };
    }
  }
  return null;
}

async function fetchEntry(candidate: string): Promise<LanguageInsight | null> {
  const controller = new AbortController();
  const timer = window.setTimeout(() => controller.abort(), TIMEOUT_MS);
  let payload: unknown;
  try {
    const response = await fetch(
      `${ENDPOINT}/${encodeURIComponent(candidate)}`,
      { signal: controller.signal, headers: { accept: "application/json" } },
    );
    if (!response.ok) return null;
    payload = await response.json();
  } catch {
    // 网络不通、被拦、超时：都当没有这条。
    return null;
  } finally {
    window.clearTimeout(timer);
  }

  return parseOnlineEntries(payload, candidate);
}

/** 线上返回的是一个条目数组，挑第一条有释义的整理成卡片要的样子。 */
export function parseOnlineEntries(
  payload: unknown,
  fallbackTerm: string,
): LanguageInsight | null {
  if (!Array.isArray(payload)) return null;

  for (const raw of payload) {
    const entry = raw as OnlineEntry;
    if (!entry || typeof entry !== "object") continue;

    const senses: string[] = [];
    const examples: LanguageInsight["examples"] = [];
    let partOfSpeech: string | undefined;

    for (const meaning of entry.meanings ?? []) {
      if (!partOfSpeech && meaning.partOfSpeech) {
        partOfSpeech = meaning.partOfSpeech;
      }
      for (const definition of meaning.definitions ?? []) {
        const text = definition.definition?.trim();
        if (text && senses.length < MAX_SENSES) senses.push(text);
        const example = definition.example?.trim();
        if (example && examples.length < MAX_EXAMPLES) {
          examples.push({ text: example });
        }
      }
    }

    if (!senses.length) continue;

    const phonetic =
      entry.phonetic?.trim() ||
      entry.phonetics?.find((item) => item.text?.trim())?.text?.trim();

    return {
      term: fallbackTerm,
      lemma: entry.word?.trim() || fallbackTerm,
      // 线上这条只有英文；卡片见它空着就把英文释义顶上去，另标「在线词典」。
      meaningsZh: [],
      // 多条词义一行一条：卡片第一行放第一条，其余收在小字里。
      definitionEn: senses.join("\n"),
      pronunciation: phonetic || undefined,
      partOfSpeech,
      collocations: [],
      examples,
      usageNotes: [],
      provider: "dictionary",
      sourceLabel: "在线词典",
    };
  }

  return null;
}
